const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={route:null,thresholds:{...Engine.defaults},cache:null,metars:null,tafs:null,flight:{aircraft:'mi8',duration:60,automatic:true,date:null,time:'12:00'},profiles:{}}, selectedDay=0, requestEpoch=0, loading=false;
try{Object.assign(state,JSON.parse(window.Native?Native.load():localStorage.getItem('polet-state')||'{}'));state.thresholds={...Engine.defaults,...state.thresholds};}catch(e){}
state.flight={aircraft:'mi8',duration:60,automatic:true,date:null,time:'12:00',...state.flight};state.profiles=state.profiles||{};if(!state.profiles[state.flight.aircraft])state.profiles[state.flight.aircraft]={...state.thresholds};state.thresholds={...Engine.defaults,...state.profiles[state.flight.aircraft]};if(state.cache?.schema!==2)state.cache=null;if(state.clouds?.schema!==2)state.clouds=null;
let cloudLoading=false;
let pending={},seq=0;
window.nativeResult=(id,body,error)=>{const p=pending[id];if(!p)return;clearTimeout(p.timer);delete pending[id];if(error){p.reject(new Error(error));return;}try{p.resolve(JSON.parse(body));}catch(e){p.reject(new Error('Источник вернул некорректный ответ. Повторите загрузку.'));}};
function call(type,...args){return new Promise((resolve,reject)=>{let id=String(++seq),timer=setTimeout(()=>{delete pending[id];reject(new Error('Источник не ответил. Проверьте интернет и повторите загрузку.'));},65000);pending[id]={resolve,reject,timer};if(window.Native){Native[type](id,...args);}else{let url;if(type==='weather')url=`https://api.open-meteo.com/v1/forecast?latitude=${args[0]}&longitude=${args[1]}&hourly=temperature_2m,visibility,wind_speed_10m,wind_direction_10m,wind_gusts_10m,cloud_cover_low,weather_code,precipitation,is_day&wind_speed_unit=ms&timezone=GMT&forecast_days=4`;else if(type==='secondaryWeather')url=`https://api.met.no/weatherapi/locationforecast/2.0/complete?lat=${args[0]}&lon=${args[1]}`;else if(type==='cloudRun')url='https://thredds.ucar.edu/thredds/catalog/grib/NCEP/GFS/Global_0p25deg/latest.xml';else if(type==='cloud')url=`https://thredds.ucar.edu/thredds/ncss/grid/grib/NCEP/GFS/Global_0p25deg/GFS_Global_0p25deg_${args[0]}.grib2?var=Geopotential_height_cloud_ceiling&var=Geopotential_height_surface&latitude=${args[1]}&longitude=${args[2]}&time_start=${encodeURIComponent(args[3])}&time_end=${encodeURIComponent(args[4])}&accept=csv`;else if(type==='gfsWeather'){const vars={surface:'Visibility_surface,Wind_speed_gust_surface,Precipitation_rate_surface',temp:'Temperature_height_above_ground',wind:'u-component_of_wind_height_above_ground,v-component_of_wind_height_above_ground'};url=`https://thredds.ucar.edu/thredds/ncss/grid/grib/NCEP/GFS/Global_0p25deg/GFS_Global_0p25deg_${args[0]}.grib2?var=${encodeURIComponent(vars[args[5]])}&latitude=${args[1]}&longitude=${args[2]}&time_start=${encodeURIComponent(args[3])}&time_end=${encodeURIComponent(args[4])}&accept=csv${args[5]==='temp'?'&vertCoord=2':args[5]==='wind'?'&vertCoord=10':''}`;}else if(type==='search')url=`https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(args[0])}&count=10&language=ru&format=json`;else url=`https://aviationweather.gov/api/data/${type==='taf'?'taf':'metar'}?ids=${args[0]}&format=json`;fetch(url).then(r=>{if(!r.ok)throw Error('Ошибка источника '+r.status);return r.status===204?'[]':r.text();}).then(x=>window.nativeResult(id,['cloud','cloudRun','gfsWeather'].includes(type)?JSON.stringify({text:x}):x,null)).catch(e=>window.nativeResult(id,null,e.message));}});}
function save(){let str=JSON.stringify(state);if(window.Native)Native.save(str);else localStorage.setItem('polet-state',str);}
function modal(title,html){$('modalTitle').textContent=title;$('modalBody').innerHTML=html;$('modal').hidden=false;document.body.style.overflow='hidden';$('closeModal').focus();}
let launchWarning=false;
function closeModal(){if(launchWarning)return;$('modal').hidden=true;document.body.style.overflow='';}
