function scoreLevel(row){if(row.score===null)return 3;const penalties=row.index.points.flatMap(p=>p.factors.map(f=>f.penalty));return penalties.some(p=>p>=1)?2:row.index.partial?3:penalties.some(p=>p>=.005)?1:0;}
