function plannedTime(){return state.flight.date&&state.flight.time?Date.parse(state.flight.date+'T'+state.flight.time+':00Z')-state.route.tz*3600000:NaN;}
function bestTitle(daylight){return daylight?'Лучший индекс среди дневных часов':'Лучший индекс среди доступных часов';}
let loadSteps=[],loadDismissed=false;
function step(id,status,detail='',retryable=status==='error'){const item=loadSteps.find(x=>x.id===id);if(item){item.status=status;item.detail=detail;item.retryable=retryable;}renderLoad();}
function networkMessage(e){const m=String(e?.message||e);if(/429/.test(m))return 'Источник ограничил частоту запросов (HTTP 429). Повторите позже.';if(/(?:HTTP|Ошибка источника|ответил).*\b[45]\d{2}\b/i.test(m))return m;return /connect|timeout|network|ответил|fetch|resolve/i.test(m)?'Источник не отвечает. Проверьте интернет; можно повторить запрос.':m;}
async function requestWithRetry(type,...args){try{return await call(type,...args);}catch(e){if(!/connect|timeout|network|ответил|fetch|resolve|502|503|504/i.test(String(e.message)))throw e;return await call(type,...args);}}
function targetHours(){const start=Date.parse(dateKey(Date.now())+'T00:00:00Z')-state.route.tz*3600000;return Array.from({length:48},(_,i)=>start+i*3600000).filter(ms=>ms+3600000>Date.now());}
