function zeroText(row){const causes=[...new Set((row.index?.points||[]).flatMap((p,i)=>p.factors.filter(f=>f.penalty===1).map(f=>f.name+(f.value!==undefined?' '+fmt(f.value,1)+' '+f.unit:'')+' · точка '+(i+1))))];return causes.length?'0% по правилу индекса: '+causes.join('; ')+'. Это не подтверждение отмены рейса.':'Индекс ниже 0,5% и округлён до 0%. Это не подтверждение отмены рейса.';}
function missingText(row){return (row.score===null?'Оценка скрыта: нет видимости или ветра для всех точек маршрута. ':row.score===0?'Есть фактор, обнуляющий оценку; другие данные получены не полностью. ':'Данные получены не полностью: результат по известным факторам, полный может быть ниже. ')+'Не хватает: '+(row.index?.missing||[]).map(x=>x.name+' (точки '+x.points.map(i=>i+1).join(', ')+')').join('; ')+'.';}
function topReasons(row){const limiting=row.index.points.reduce((best,p,i)=>p.raw<row.index.points[best].raw?i:best,0);const factors=row.index.points[limiting].factors.filter(f=>f.penalty>=.005).map(f=>({...f,i:limiting})).sort((a,b)=>b.penalty-a.penalty);const seen=new Set(),out=[];for(const f of factors){if(seen.has(f.name))continue;seen.add(f.name);const value=f.value===undefined?'':f.clear?'':(f.name==='Осадки'?fmtRain(f.value).replace('&lt;','<'):f.name==='Облачный потолок'?fmtHeight(f.value,!!f.source?.includes('GFS')):fmt(f.value,1))+(f.gust!==undefined?' / порывы '+fmt(f.gust,1):'')+' '+(f.name==='Облачный потолок'?'':f.unit||'');const threshold=({'Видимость':`внимание ≤${state.thresholds.visYellow} м; высокий ≤${state.thresholds.visRed} м`,'Ветер / порывы':`высокий: ветер ≥${state.thresholds.windRed}, порывы ≥${state.thresholds.gustRed} м/с`,'Осадки':`высокий ≥${state.thresholds.rainRed} мм/ч`,'Облачный потолок':`внимание ≤${state.thresholds.cloudYellow} м; высокий ≤${state.thresholds.cloudRed} м`})[f.name]||'';const time=local(row.ms+state.flight.duration*60000*f.i/4).toISOString().slice(11,16);out.push(`${f.name}: ${value} · ${pointName(f.i)} · ${time} · ${f.source||'прогноз погоды'}${f.penalty===1?' — высокий порог, оценка 0%':''}`);}return out.length?out:row.score===null?['Нет доступных факторов для расчёта']:['Полученные факторы ниже порогов внимания'];}
function coverageDetail(row){modal('Погодные данные',`${factorImpacts(row)}<p>Цветом выделены погодные параметры. При неполных данных оценка предварительная. Решение о рейсе принимает перевозчик.</p><div class="coverage-list">${row.coverage.list.map(x=>`<div class="coverage-item"><span>${x.name}</span><b class="${x.status==='есть'?'green':x.status==='частично'?'yellow':'gray'}">${x.status}</b></div>`).join('')}</div>`);}
function renderObservations(){const el=$('observations');const codes=state.route?airportCodes('metar'):[];el.hidden=!codes.length;if(!codes.length)return;let obs=state.metars;el.innerHTML='<h2>Фактическая погода аэродромов</h2><p class="caption">METAR · отдельные наблюдения, не прогноз месторождения</p><p class="caption">'+esc(airportDescription('metar'))+'</p>';if(!obs){el.innerHTML+='<p>Сводки пока не загружены.</p>';return;}if(obs.error){el.innerHTML+=`<p>${esc(obs.error)}</p>`;return;}for(const code of [...new Set(codes)]){const m=(Array.isArray(obs.data)?obs.data:[]).find(m=>m.icaoId===code);if(!m){el.innerHTML+=`<div class="obs"><b>${esc(code)}</b><small>Сводка недоступна. Это не означает хорошую погоду.</small></div>`;continue;}const time=Number(m.obsTime)*1000,age=Number.isFinite(time)?(Date.now()-time)/60000:Infinity;const clouds=(m.clouds||[]).filter(c=>['BKN','OVC','VV'].includes(c.cover)&&Engine.valid(c.base));const ceiling=clouds.length?Math.min(...clouds.map(c=>c.base))*0.3048:null;const vis=Engine.visibilityMeters(m.visib);const visText=Engine.valid(vis)?fmtVisibility(vis)+(String(m.visib).includes('+')||String(m.visib).startsWith('P')?' и более':''):'не указана';el.innerHTML+=`<div class="obs"><b>${esc(code)} ${age>90?'· сводка устарела':''}</b><small>${Number.isFinite(time)?'Наблюдение: '+local(time).toISOString().slice(0,16).replace('T',' '):'Время наблюдения неизвестно'} · UTC+${state.route.tz}</small><small>Видимость: ${visText}<br>Ветер: ${fmt(Engine.valid(m.wspd)?m.wspd*0.514444:null,1)} м/с<br>Нижняя граница BKN/OVC/VV: ${ceiling===null?'не указана':fmt(ceiling)+' м'}</small><p class="mono">${esc(m.rawOb||'')}</p></div>`;}}

function aircraftSelect(id){const groups=[...new Set(Catalog.aircraft.map(a=>a.group))];return `<select id="aircraftSelect">${groups.map(g=>`<optgroup label="${esc(g)}">${Catalog.aircraft.filter(a=>a.group===g).map(a=>`<option value="${a.id}" ${a.id===id?'selected':''}>${esc(a.name)}</option>`).join('')}</optgroup>`).join('')}</select>`;}
function estimatedDuration(a,b,aircraft){const model=Catalog.get(aircraft),speed=model.cruise||225;return Math.max(5,Math.ceil(Engine.routePoints(a,b).distance/speed*60/5)*5);}
function formToday(){const tz=Number($('tzInput')?.value)||state.route?.tz||7;return new Date(Date.now()+tz*3600000).toISOString().slice(0,10);}
function flightFields(){const f=state.flight,today=formToday(),max=new Date(Date.parse(today+'T00:00:00Z')+86400000).toISOString().slice(0,10);return `<div class="field-group"><h3>ВАШ РЕЙС</h3><label>Вертолёт</label>${aircraftSelect(f.aircraft)}<div class="model-hint">На вахтовых рейсах часто летают Ми-8. У вас может быть другой — выберите его 🙂</div><div id="aircraftInfo" class="aircraft-info"></div><div class="two"><div><label>Дата вылета</label><input id="flightDateInput" type="date" min="${today}" max="${max}" value="${f.date&&f.date>=today&&f.date<=max?f.date:today}"></div><div><label>Время вылета</label><input id="flightTimeInput" type="time" value="${esc(f.time)}"></div></div><label class="check-label"><input type="checkbox" id="autoDuration" ${f.automatic!==false?'checked':''}>Рассчитывать время в пути автоматически</label><label>~ Время в пути, минут</label><input id="durationInput" type="number" min="5" max="1440" value="${f.duration}"><p id="durationEstimate" class="caption"></p><p class="caption">~ означает ориентировочно. Расстояние по прямой / крейсерская скорость. Без поправок на ветер, взлёт, посадку и реальный маршрут. Можно указать время из расписания вручную.</p></div>`;}
function bindFlightFields(){const update=()=>{const a=Catalog.get($('aircraftSelect').value);$('aircraftInfo').innerHTML=`<b>${esc(a.name)}</b><p>${esc(a.note||'')}</p><p>~ Скорость для оценки: ${a.cruise||225} км/ч${a.cruise?'':' · временный ориентир Ми-8, скорость выбранной модели не подтверждена'}.</p><p class="caption">${esc(a.speedSource||a.source||'Справочный ориентир по семейству Ми-8')} · Погодные минимумы конкретного борта не подключены.</p>`;$('durationInput').disabled=$('autoDuration').checked;try{const pa={lat:Number($('aLat').value.replace(',','.')),lon:Number($('aLon').value.replace(',','.'))},pb={lat:Number($('bLat').value.replace(',','.')),lon:Number($('bLon').value.replace(',','.'))};if(!['aLat','aLon','bLat','bLon'].every(id=>$(id).value.trim())||Math.abs(pa.lat)>90||Math.abs(pb.lat)>90||Math.abs(pa.lon)>180||Math.abs(pb.lon)>180)throw Error();const km=Engine.routePoints(pa,pb).distance,duration=estimatedDuration(pa,pb,a.id);if(!Number.isFinite(duration))throw Error();if($('autoDuration').checked)$('durationInput').value=duration;$('durationEstimate').textContent=`~ ${Math.round(km)} км · ~ ${duration} мин при ${a.cruise||225} км/ч`;}catch(e){$('durationEstimate').textContent='Укажите координаты обеих точек — время рассчитается само.';}};for(const id of ['aLat','aLon','bLat','bLon'])$(id).addEventListener('input',update);$('aircraftSelect').onchange=update;$('autoDuration').onchange=update;$('tzInput').addEventListener('input',()=>{const today=formToday(),max=new Date(Date.parse(today+'T00:00:00Z')+86400000).toISOString().slice(0,10);$('flightDateInput').min=today;$('flightDateInput').max=max;});document.querySelectorAll('.airportPreset').forEach(btn=>btn.addEventListener('click',()=>setTimeout(update,0)));update();}
function readFlight(a,b,tz){const aircraft=$('aircraftSelect').value,date=$('flightDateInput').value,time=$('flightTimeInput').value,automatic=$('autoDuration').checked,duration=automatic?estimatedDuration(a,b,aircraft):Number($('durationInput').value);const today=new Date(Date.now()+tz*3600000).toISOString().slice(0,10),max=new Date(Date.parse(today+'T00:00:00Z')+86400000).toISOString().slice(0,10);if(date<today||date>max||!/^\d{4}-\d{2}-\d{2}$/.test(date))throw Error('Выберите сегодня или завтра.');if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(time))throw Error('Укажите корректное время вылета.');if(!Number.isInteger(duration)||duration<5||duration>1440)throw Error('Время в пути — от 5 до 1440 минут. Для такого маршрута проверьте расписание.');return {aircraft,date,time,duration,automatic};}
function showLaunchWarning(){const previous=!$('modal').hidden?{title:$('modalTitle').textContent,nodes:Array.from($('modalBody').childNodes)}:null;launchWarning=true;modal('Важно перед использованием',`<div class="note">Приложение для пассажиров. Оно не является инструкцией к полёту, авиационным прогнозом или разрешением на вылет.</div><p>Данные получены из погодных сервисов и могут быть неполными, неточными или устаревшими. Цвета и погодный индекс в процентах — ориентировочная оценка загруженных факторов, а не вероятность вылета. Даже 100% не гарантируют, что вертолёт полетит.</p><p>Условия на высоте, ограничения борта, экипажа, площадок и решение перевозчика могут отличаться. Не используйте приложение для планирования, выполнения полётов и принятия решений о безопасности. Уточняйте статус рейса у перевозчика или диспетчера.</p><p>Разработчик не гарантирует вылет, точность прогноза или пригодность оценки для конкретного рейса. Используя приложение, вы понимаете эти ограничения.</p><button id="acceptWarning" class="primary">Понятно, открыть приложение</button>`);$('closeModal').hidden=true;$('acceptWarning').onclick=()=>{launchWarning=false;$('closeModal').hidden=false;closeModal();if(previous){$('modalTitle').textContent=previous.title;$('modalBody').replaceChildren(...previous.nodes);$('modal').hidden=false;document.body.style.overflow='hidden';$('closeModal').focus();}};$('acceptWarning').focus();}
function renderCloudSource(){const el=$('cloudPanel');if(!state.route)return;const c=state.clouds;let text=cloudLoading?'Загружаем отдельный прогноз высоты облаков…':c?.error?`Не удалось обновить: ${esc(c.error)}. Повторим при обновлении погоды.`:!c?.data?'Ждём загрузки источника.':'Ответ GFS получен. Наличие высоты для каждого дня и точки смотрите в статусе загрузки.';const fresh=c?.data&&Date.now()-c.fetchedAt<3*3600000&&Date.now()-c.runMs<24*3600000;el.innerHTML=`<h2>~ Высота облаков на маршруте</h2><p>${text}</p>${c?.data&&Engine.valid(c.runMs)?`<p class="caption">Выпуск GFS: ${local(c.runMs).toISOString().slice(0,16).replace('T',' ')} · UTC+${state.route.tz}${fresh?'':' · данные устарели, в индекс не включены'}</p>`:''}<p class="caption">NOAA GFS через UCAR / Unidata · сетка 0,25° · шаг 3 часа. Высота облачного потолка над модельной поверхностью. Между сроками показываем меньшую высоту соседних сроков. Это ~ ориентир, а не измерение над площадкой. Если GFS не прогнозирует облачный потолок, показываем это словами и учитываем состояние в оценке. Это не означает отсутствия всех облаков. Между числовой высотой и отсутствием потолка используем меньшую числовую высоту. При пропуске или ошибке состояние остаётся неизвестным.</p>`;}
function renderTaf(){
 const el=$('tafPanel'),codes=airportCodes('taf');el.hidden=!codes.length;if(!codes.length)return;
 el.innerHTML='<h2>Авиационный прогноз облаков</h2><p class="caption">TAF · только аэродромы, не весь маршрут</p><p class="caption">'+esc(airportDescription('taf'))+'</p>';
 if(!state.tafs){el.innerHTML+='<p>Прогнозы пока не загружены.</p>';return;}
 if(state.tafs.error){el.innerHTML+=`<p>${esc(state.tafs.error)}</p>`;return;}
 for(const code of codes){const t=(state.tafs.data||[]).find(t=>t.icaoId===code);if(!t){el.innerHTML+=`<div class="obs"><b>${esc(code)}</b><small>TAF недоступен. Высоту облаков не подменяем процентом облачности.</small></div>`;continue;}
 const times=[t.validTimeFrom,t.validTimeTo].map(x=>Engine.valid(x)?local(x*1000).toISOString().slice(5,16).replace('T',' '):'срок неизвестен');
 const matching=[0,4].some(i=>matchedTaf(i)?.icaoId===code);
 el.innerHTML+=`<div class="obs"><b>${esc(code)}${!matching?' · не включён в индекс':''}</b><small>Действует ${times[0]} → ${times[1]} · UTC+${state.route.tz}</small><small>${matching?'Используем высоту облаков и худшие условия временных групп в часы действия.':'Проверьте расстояние между координатами точки и аэродромом, а также свежесть загрузки.'}</small><p class="mono">${esc(t.rawTAF||'')}</p></div>`;
 }
}
render();if(state.route&&(!state.cache||!state.clouds||Date.now()-state.cache.fetchedAt>20*60000||aviationNeedsRefresh()))refresh();setInterval(()=>{if(!document.hidden&&state.route&&!loading)refresh();},20*60000);document.addEventListener('visibilitychange',()=>{if(!document.hidden){render();if(state.route&&!loading&&(!state.cache||!state.clouds||Date.now()-state.cache.fetchedAt>20*60000||aviationNeedsRefresh()))refresh();}});

showLaunchWarning();
window.onAppResume=()=>{if(!launchWarning)showLaunchWarning();if(state.route){render();if(!loading&&(!state.cache||!state.clouds||Date.now()-state.cache.fetchedAt>20*60000||aviationNeedsRefresh()))refresh();}};
